        .iter()
        .filter(|(_, n)| **n >= 2)
        .max_by_key(|(pair, n)| (**n, std::cmp::Reverse(**pair)))
        .map(|(pair, _)| *pair)
}

pub fn merge(ids: &[u32], pair: (u32, u32), new_id: u32) -> Vec<u32> {
    let mut out = ids.to_vec();
    for (i, w) in out.windows(2).enumerate() {
        if (w[0], w[1]) == pair {
            out.splice(i..i + 2, [new_id]);
        }
    }
    out
